import { readFile, writeFile } from "fs/promises";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { createWorkspace, teardownWorkspace, Workspace } from "@tigrisdata/agent-kit";

const TRIAL_ID_PATH = "/logs/artifacts/trial_id";
const POOL_JSON_PATH = "/home/user/ws-pool/pool.json";
const TGRIS_ENDPOINT = "REDACTED";

const normalizeName = (name: string) =>
  name.toLowerCase().replace(/[^a-z0-9.-]/g, "-");

const requireCredentials = (workspace: Workspace) => {
  if (!workspace.credentials?.accessKeyId || !workspace.credentials?.secretAccessKey) {
    throw new Error("Workspace credentials are missing scoped access keys.");
  }
  return workspace.credentials;
};

const main = async () => {
  const trialId = (await readFile(TRIAL_ID_PATH, "utf8")).trim();
  const names = [1, 2, 3, 4].map((index) =>
    normalizeName(`pool-agent-${trialId}-${index}`)
  );

  const workspaceResponses = await Promise.all(
    names.map((name) =>
      createWorkspace(name, {
        ttl: { days: 1 },
        credentials: { role: "Editor" },
      })
    )
  );

  const workspaces = workspaceResponses.map((response, index) => {
    if ("error" in response) {
      throw response.error;
    }
    return {
      name: names[index],
      workspace: response.data,
    };
  });

  await Promise.all(
    workspaces.map(async ({ name, workspace }) => {
      const credentials = requireCredentials(workspace);
      const client = new S3Client({
        region: "REDACTED",
        endpoint: TGRIS_ENDPOINT,
        credentials: {
          accessKeyId: credentials.accessKeyId,
          secretAccessKey: credentials.secretAccessKey,
        },
      });

      await client.send(
        new PutObjectCommand({
          Bucket: workspace.bucket,
          Key: "init.txt",
          Body: name,
        })
      );
    })
  );

  const poolSummary = workspaces.map(({ name, workspace }) => ({
    name,
    bucket: workspace.bucket,
  }));
  await writeFile(POOL_JSON_PATH, JSON.stringify(poolSummary, null, 2));

  const teardownResults = await Promise.allSettled(
    workspaces.map(({ workspace }) => teardownWorkspace(workspace))
  );
  teardownResults.forEach((result, index) => {
    if (result.status === "rejected") {
      console.error(
        `Failed to teardown workspace ${workspaces[index].name}:`,
        result.reason
      );
    } else if ("error" in result.value) {
      console.error(
        `Failed to teardown workspace ${workspaces[index].name}:`,
        result.value.error
      );
    }
  });
};

main()
  .then(() => {
    process.exit(0);
  })
  .catch((error) => {
    console.error("Workspace pool provisioning failed:", error);
    process.exit(1);
  });
